import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays, getLastDayOfMonth } from './dates.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate issueDate format and value
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');

  // Calculate due date based on terms
  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = getLastDayOfMonth(issueDate);
  }

  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  const customer = customerResult.value;

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate quantity is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discount: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for one line: quantity times unit price.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate invoice totals: subtotal, discount, VAT, voucher, and total.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineDiscount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
    return sum + Math.max(0, lineDiscount);
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineTotal$ = lineTotal(line);
    const lineDiscount = lineTotal$ * (line.discountPercent ?? 0) / 100;
    const amountAfterDiscount = Math.max(0, lineTotal$ - lineDiscount);
    const lineVat = amountAfterDiscount * (line.vatRate ?? 0) / 100;
    return sum + roundCents(lineVat);
  }, 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {object} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer to determine tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  const discount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    // Increase qty on existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {object} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice: assign a number and change status to 'issued'.
 * @param {object} invoice
 * @param {Array<string>} existingNumbers
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return fail(numberResult.error);

  return ok({
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  });
}

/**
 * Apply a voucher to an invoice (fixed amount off after VAT).
 * @param {object} invoice
 * @param {{ code: string, amount: number }} voucher
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check invoice doesn't already have a voucher
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Check amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

