      { sku: 'COPY-HOUR', name: 'Copywriting', qty: 2, unitPrice: 6000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line 1: 42500, discount 2125, after 40375, VAT 8479
  // Line 2: 28500, discount 712.5, after 27787.5, VAT 5835
  // Line 3: 12000, discount 0, after 12000, VAT 2520
  // Subtotal: 83000
  // Total discount: 2837.5
  // Total VAT: 16834
  // Total: 97134 (approximately, accounting for rounding)
  assert.ok(totals.subtotal > 80000);
  assert.ok(totals.vat > 16000);
});

test('invoiceTotals returns independent objects', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);

  assert.notStrictEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals with large number of lines', () => {
  const lines = [];
  for (let i = 0; i < 100; i++) {
    lines.push({
      sku: `SKU-${i}`,
      name: `Product ${i}`,
      qty: 1,
      unitPrice: 1000,
      vatRate: 21,
      discountPercent: 0,
    });
  }

  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines,
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 121000);
});

test('invoiceTotals with fractional VAT calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set', qty: 1, unitPrice: 980, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line: 980, discount = 49, after = 931, VAT = 931 * 0.21 = 195.51 → 196
  assert.equal(totals.subtotal, 980);
  assert.equal(totals.discount, 49);
  assert.equal(totals.vat, 196);
});

